 */

class SuppliersController
{
    private static bool $columnsEnsured = false;
    private static bool $historyTableEnsured = false;
    private static bool $walkbyEnsured = false;

    private function ensureSuppliersTable(PDO $db): void
    {
        // Create the suppliers table if missing so the feature self-heals on an
        // existing v1 database without waiting for "Verify & build" (the table is
        // otherwise only created by schema.sql). Mirrors ensureSupplierHistoryTable.
        $db->exec("CREATE TABLE IF NOT EXISTS suppliers (
            id INT AUTO_INCREMENT PRIMARY KEY,
            uid VARCHAR(50) UNIQUE DEFAULT NULL,
            name VARCHAR(190) NOT NULL,
            phone VARCHAR(50) NULL,
            email VARCHAR(190) NULL,
            address VARCHAR(255) NULL,
            note TEXT NULL,
            created_by INT NULL,
            edited_by INT NULL,
            created_at DATETIME NOT NULL,
            updated_at DATETIME NULL,
            deleted_at DATETIME NULL,
            deleted_by INT NULL,
            delete_reason TEXT NULL
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
    }

    private function ensureSuppliersColumns(PDO $db): void
    {
        if (self::$columnsEnsured) {
            return;
        }
        self::$columnsEnsured = true;

        $this->ensureSuppliersTable($db);

        $columns = [
            'uid'           => 'VARCHAR(50) UNIQUE DEFAULT NULL',
            'phone'         => 'VARCHAR(50) DEFAULT NULL',
            'email'         => 'VARCHAR(100) DEFAULT NULL',
            'address'       => 'VARCHAR(255) DEFAULT NULL',
            'note'          => 'TEXT NULL',
            'is_walkby'     => 'TINYINT(1) NOT NULL DEFAULT 0',
            'edited_by'     => 'INT NULL',
            'deleted_at'    => 'DATETIME NULL',
            'deleted_by'    => 'INT NULL',
            'delete_reason' => 'TEXT NULL',
        ];

        foreach ($columns as $column => $definition) {
            $stmt = $db->prepare("SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'suppliers' AND COLUMN_NAME = :column");
            $stmt->execute(['column' => $column]);
            if (!$stmt->fetch()) {
                $db->exec("ALTER TABLE suppliers ADD COLUMN $column $definition");
            }
        }
    }

    private function ensureSupplierHistoryTable(PDO $db): void
    {
        if (self::$historyTableEnsured) {
            return;
        }
        self::$historyTableEnsured = true;

        $db->exec("CREATE TABLE IF NOT EXISTS supplier_history (
            id INT AUTO_INCREMENT PRIMARY KEY,
            supplier_id INT NOT NULL,
            edited_by INT NULL,
            action VARCHAR(50) NOT NULL,
            changes JSON NULL,
            reason TEXT NULL,
            created_at DATETIME NOT NULL,
            FOREIGN KEY (supplier_id) REFERENCES suppliers(id),
            FOREIGN KEY (edited_by) REFERENCES users(id) ON DELETE SET NULL
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");

        try {
            $db->exec("ALTER TABLE supplier_history MODIFY edited_by INT NULL");
        } catch (\Throwable $e) {
            error_log("Suppressed exception in " . __METHOD__ . ": " . $e->getMessage());
        }
    }

    // Make sure the built-in "Walk-by" supplier exists. It represents one-off /
    // unofficial sellers (someone who walked by, not a registered supplier). It is
    // a normal supplier row (has history, balance, etc.) but flagged is_walkby = 1
    // so the purchase form knows to ask "who was this person?" per purchase. Only
    // created once; if the user deletes it they can restore it like any supplier.
    private function ensureWalkbySupplier(PDO $db): void
    {
        if (self::$walkbyEnsured) {
            return;
        }
        self::$walkbyEnsured = true;

        $exists = $db->query('SELECT id FROM suppliers WHERE is_walkby = 1 LIMIT 1')->fetch();
        if ($exists) return;

        $uid = 'SUP-' . date('Ymd') . '-WALKBY';
        $stmt = $db->prepare('INSERT INTO suppliers (uid, name, note, is_walkby, created_by, created_at) VALUES (:uid, :name, :note, 1, :created_by, NOW())');
        $stmt->execute([
            'uid'        => $uid,
            'name'       => 'Walk-by (one-off seller)',
            'note'       => 'Built-in supplier for one-off / unofficial sellers. Pick this on a purchase when you buy from someone who is not a registered supplier; you then note who they were on that purchase.',
            'created_by' => $_SESSION['user_id'] ?? null,
        ]);
    }

    public function index(): void
    {
        $db = Database::getConnection();
        $this->ensureSuppliersColumns($db);
        $this->ensureWalkbySupplier($db);
        if (function_exists('ensureDefaultCatalogSeeded')) {
            ensureDefaultCatalogSeeded($db);
        }

        $showDeleted = isset($_GET['show_deleted']) && $_GET['show_deleted'] === 'true';

        if ($showDeleted) {
            $suppliers = $db->query('SELECT * FROM suppliers ORDER BY id DESC')->fetchAll();
        } else {
            $suppliers = $db->query('SELECT * FROM suppliers WHERE deleted_at IS NULL ORDER BY id DESC')->fetchAll();
        }

        Response::json(['suppliers' => $suppliers]);
    }

    public function store(array $data): void
    {
        try {
            $name = trim($data['name'] ?? '');
            if ($name === '') {
                Response::json(['error' => 'Supplier name required'], 400);
                return;
            }

            $db = Database::getConnection();
            $this->ensureSuppliersColumns($db);
            $this->ensureSupplierHistoryTable($db);

            // Generate UID: SUP-YYYYMMDD-XXXXXX (matching customer/product format)
            $uid = 'SUP-' . date('Ymd') . '-' . strtoupper(substr(uniqid(), -6));

            $stmt = $db->prepare('INSERT INTO suppliers (uid, name, phone, email, address, note, created_by, created_at) VALUES (:uid, :name, :phone, :email, :address, :note, :created_by, NOW())');
            $stmt->execute([
                'uid'        => $uid,
                'name'       => $name,
                'phone'      => $data['phone'] ?? null,
                'email'      => $data['email'] ?? null,
                'address'    => $data['address'] ?? null,
                'note'       => $data['note'] ?? null,
                'created_by' => $_SESSION['user_id'] ?? null,
            ]);

            $supplierId = (int)$db->lastInsertId();

            // Log creation
            $histStmt = $db->prepare('INSERT INTO supplier_history (supplier_id, edited_by, action, changes, created_at) VALUES (:sid, :by, :action, :changes, NOW())');
            $histStmt->execute([
                'sid'     => $supplierId,
                'by'      => $_SESSION['user_id'] ?? 1,
                'action'  => 'created',
                'changes' => json_encode(['uid' => $uid, 'name' => $name, 'phone' => $data['phone'] ?? null, 'email' => $data['email'] ?? null, 'address' => $data['address'] ?? null, 'note' => $data['note'] ?? null]),
            ]);

            SystemLog::write('suppliers', 'created', $supplierId, $name, json_encode([
                'uid' => $uid,
                'phone' => $data['phone'] ?? null,
                'email' => $data['email'] ?? null,
                'status' => 'active'
            ]));

            Response::json(['id' => $supplierId, 'uid' => $uid], 201);
        } catch (\Throwable $e) {
            error_log('[SUPPLIERS STORE ERROR] ' . $e->getMessage());
            Response::json(['error' => 'Failed to create supplier. Please check server error logs.'], 500);
        }
    }

