​‌‌‌​‌​‌​‌‌​‌‌‌​​‌‌​​​​‌​‌‌‌​‌​‌​‌‌‌​‌​​​‌‌​‌​​​​‌‌​‌‌‌‌​‌‌‌​​‌​​‌‌​‌​​‌​‌‌‌‌​‌​​‌‌​​‌​‌​‌‌​​‌​​​​‌​​​​​​‌‌‌​‌‌​​‌‌​‌​​‌​‌‌​‌‌‌‌​‌‌​‌‌​​​‌‌​​​​‌​‌‌‌​‌​​​‌‌​‌​​‌​‌‌​‌‌‌‌​‌‌​‌‌‌​​​‌​​​​​​‌‌​​​​‌​‌‌​‌‌‌​​‌‌​​‌​​​​‌​​​​​​‌​​‌‌​‌​‌​‌​‌​‌​‌​‌​​‌‌​‌​‌​‌​​​​‌​​​​​​‌​​​​‌​​‌​​​‌​‌​​‌​​​​​​‌​‌​​‌​​‌​​​‌​‌​‌​​​‌‌​​‌​‌​‌​‌​‌​‌​​‌‌​‌​​​‌​‌​‌​​​‌​​​​‌​​​​​​‌​​‌​​‌​‌​​‌‌​‌​‌​​‌‌​‌​‌​​​‌​‌​‌​​​‌​​​‌​​‌​​‌​‌​​​​​‌​‌​‌​‌​​​‌​​​‌​‌​‌​​‌‌​​​‌​‌‌​​‌​​‌​‌‌‌​﻿‍ */

            if ($supplier['deleted_at'] !== null) {
                Response::json(['error' => 'Archived supplier cannot be updated. Please restore first.'], 400);
                return;
            }

            if (!empty($supplier['is_walkby']) || str_starts_with(strtolower(trim((string)$supplier['name'])), 'walk-by')) {
                Response::json(['error' => 'The default Walk-by supplier profile is a protected system record and cannot be edited'], 400);
                return;
            }

            // Track changes
            $changes = [];
            foreach (['name', 'phone', 'email', 'address', 'note'] as $field) {
                if (array_key_exists($field, $data) && (string)($data[$field] ?? '') !== (string)($supplier[$field] ?? '')) {
                    $changes[$field] = ['from' => $supplier[$field], 'to' => $data[$field]];
                }
            }

            $stmt = $db->prepare('UPDATE suppliers SET name = :name, phone = :phone, email = :email, address = :address, note = :note, edited_by = :edited_by, updated_at = NOW() WHERE id = :id');
            $stmt->execute([
                'name'      => $data['name'] ?? $supplier['name'],
                'phone'     => $data['phone'] ?? $supplier['phone'],
                'email'     => $data['email'] ?? $supplier['email'],
                'address'   => $data['address'] ?? $supplier['address'],
                'note'      => $data['note'] ?? $supplier['note'],
                'edited_by' => $_SESSION['user_id'] ?? null,
                'id'        => $id,
            ]);

            if (!empty($changes)) {
                $histStmt = $db->prepare('INSERT INTO supplier_history (supplier_id, edited_by, action, changes, created_at) VALUES (:sid, :by, :action, :changes, NOW())');
                $histStmt->execute([
                    'sid'     => $id,
                    'by'      => $_SESSION['user_id'] ?? 1,
                    'action'  => 'updated',
                    'changes' => json_encode($changes),
                ]);

                SystemLog::write('suppliers', 'updated', (int)$id, $supplier['name'], json_encode(array_merge(
                    ['uid' => $supplier['uid'] ?? null],
                    $changes
                )));
            }

            Response::json(['ok' => true]);
        } catch (\Throwable $e) {
            error_log('[SUPPLIERS UPDATE ERROR] ' . $e->getMessage());
            Response::json(['error' => 'Failed to update supplier. Please check server error logs.'], 500);
        }
    }

    public function destroy(string $id): void
    {
        try {
            $db = Database::getConnection();
            $this->ensureSuppliersColumns($db);
            $this->ensureSupplierHistoryTable($db);

            $stmt = $db->prepare('SELECT id, name, uid, is_walkby, deleted_at FROM suppliers WHERE id = :id');
            $stmt->execute(['id' => $id]);
            $supplier = $stmt->fetch();
            if (!$supplier) {
                Response::json(['error' => 'Supplier not found'], 404);
                return;
            }

            if ($supplier['deleted_at'] !== null) {
                Response::json(['error' => 'Supplier is already deleted'], 400);
                return;
            }

            if (!empty($supplier['is_walkby']) || str_starts_with(strtolower(trim((string)$supplier['name'])), 'walk-by')) {
                Response::json(['error' => 'Walk-by supplier is a protected system record and cannot be deleted.'], 400);
                return;
            }

            $debtStmt = $db->prepare("SELECT total, amount_paid FROM purchases WHERE supplier_id = :id AND deleted_at IS NULL AND payment_status IN ('unpaid', 'partial')");
            $debtStmt->execute(['id' => $id]);
            $owed = '0';
            foreach ($debtStmt->fetchAll() as $pur) {
                $due = Decimal::sub((string)$pur['total'], (string)($pur['amount_paid'] ?? '0'));
                if (Decimal::comp($due, '0') > 0) {
                    $owed = Decimal::add($owed, $due);
                }
            }
            if (Decimal::comp($owed, '0') > 0) {
                Response::json(['error' => 'Cannot delete supplier with outstanding debt. Please settle all payables first.'], 400);
                return;
            }

            $input = json_decode(file_get_contents('php://input'), true);
            $deleteReason = trim($input['delete_reason'] ?? '');
            if ($deleteReason === '') {
                Response::json(['error' => 'Deletion reason is required'], 400);
                return;
            }

            $stmt = $db->prepare('UPDATE suppliers SET deleted_at = NOW(), deleted_by = :deleted_by, delete_reason = :delete_reason WHERE id = :id');
            $stmt->execute([
                'deleted_by'    => $_SESSION['user_id'] ?? null,
                'delete_reason' => $deleteReason,
                'id'            => $id,
            ]);

            $histStmt = $db->prepare('INSERT INTO supplier_history (supplier_id, edited_by, action, reason, created_at) VALUES (:sid, :by, :action, :reason, NOW())');
            $histStmt->execute([
                'sid'    => $id,
                'by'     => $_SESSION['user_id'] ?? 1,
                'action' => 'deleted',
                'reason' => $deleteReason,
            ]);

            SystemLog::write('suppliers', 'deleted', (int)$id, $supplier['name'], json_encode([
                'uid' => $supplier['uid'] ?? null,
                'reason' => $deleteReason,
                'status' => 'deleted'
            ]));

            Response::json(['ok' => true]);
        } catch (\Throwable $e) {
            error_log('[SUPPLIERS DESTROY ERROR] ' . $e->getMessage());
            Response::json(['error' => 'Failed to delete supplier. Please check server error logs.'], 500);
        }
    }

    public function restore(string $id): void
    {
        try {
            $db = Database::getConnection();
            $this->ensureSuppliersColumns($db);
            $this->ensureSupplierHistoryTable($db);

            $stmt = $db->prepare('SELECT id, name, deleted_at FROM suppliers WHERE id = :id');
            $stmt->execute(['id' => $id]);
            $supplier = $stmt->fetch();
            if (!$supplier) {
                Response::json(['error' => 'Supplier not found'], 404);
                return;
            }

            if ($supplier['deleted_at'] === null) {
                Response::json(['error' => 'Supplier is not deleted'], 400);
                return;
            }

            $input = json_decode(file_get_contents('php://input'), true);
            $restoreReason = trim($input['restore_reason'] ?? '');
            if ($restoreReason === '') {
                Response::json(['error' => 'Restore reason is required'], 400);
                return;
            }

            $stmt = $db->prepare('UPDATE suppliers SET deleted_at = NULL, deleted_by = NULL, delete_reason = NULL WHERE id = :id');
            $stmt->execute(['id' => $id]);

            $histStmt = $db->prepare('INSERT INTO supplier_history (supplier_id, edited_by, action, reason, created_at) VALUES (:sid, :by, :action, :reason, NOW())');
            $histStmt->execute([
                'sid'    => $id,
                'by'     => $_SESSION['user_id'] ?? 1,
                'action' => 'restored',
                'reason' => $restoreReason,
            ]);

            SystemLog::write('suppliers', 'restored', (int)$id, $supplier['name'], json_encode([
                'uid' => $supplier['uid'] ?? null,
                'reason' => $restoreReason,
                'status' => 'active'
            ]));

            Response::json(['ok' => true]);
        } catch (\Throwable $e) {
            error_log('[SUPPLIERS RESTORE ERROR] ' . $e->getMessage());
            Response::json(['error' => 'Failed to restore supplier. Please check server error logs.'], 500);
        }
    }

    public function history(string $id): void
    {
        $db = Database::getConnection();
        $this->ensureSuppliersColumns($db);
        $this->ensureSupplierHistoryTable($db);

        $stmt = $db->prepare('SELECT s.*, u.username as creator_name, u2.username as editor_name FROM suppliers s LEFT JOIN users u ON s.created_by = u.id LEFT JOIN users u2 ON s.edited_by = u2.id WHERE s.id = :id');
        $stmt->execute(['id' => $id]);
        $supplier = $stmt->fetch();
        if (!$supplier) {
            Response::json(['error' => 'Supplier not found'], 404);
            return;
        }

        $stmt = $db->prepare('SELECT sh.*, u.username FROM supplier_history sh LEFT JOIN users u ON sh.edited_by = u.id WHERE sh.supplier_id = :id ORDER BY sh.created_at DESC');
        $stmt->execute(['id' => $id]);
        $history = $stmt->fetchAll();

        Response::json(['supplier' => $supplier, 'history' => $history]);
    }
}

